    26	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
    27	            if (reservation.isPaid() && coversNight) {
    28	                occupying.add(reservation);
    29	            }
    30	        }
    31	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
    32	
    33	        StringBuilder csv = new StringBuilder();
    34	        csv.append("room,type,reservation,guest,check_in,check_out\n");
    35	        for (Reservation reservation : occupying) {
    36	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
    37	            String guestName = reservation.guest().name().replace(',', ' ');
    38	            csv.append(room.number()).append(',')
    39	                    .append(room.type()).append(',')
    40	                    .append(reservation.id()).append(',')
    41	                    .append(guestName).append(',')
    42	                    .append(reservation.checkIn()).append(',')
    43	                    .append(reservation.checkOut()).append('\n');
    44	        }
    45	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
    46	        return csv.toString();
    47	    }
    48	}
